// ============================================
// VALIDATION INPUT - LLM Call Stream (BYOT)
// ============================================

const input = $input.first().json;
const body = input.body || input;
const ctx = body.context || {};

const errors = [];

// --- REQUIRED: provider ---
const provider = (body.provider || ctx.provider || '').toLowerCase();
const validProviders = ['anthropic', 'openai', 'mistral', 'google'];
if (!provider) {
  errors.push('provider requis (anthropic, openai, mistral)');
} else if (!validProviders.includes(provider)) {
  errors.push(`provider invalide: ${provider}`);
}

// --- REQUIRED: model ---
const model = body.model || ctx.model;
if (!model || typeof model !== 'string') {
  errors.push('model requis');
}

// --- REQUIRED: api_key (BYOT - NO FALLBACK) ---
const apiKey = body.api_key || ctx.api_key;
if (!apiKey || typeof apiKey !== 'string') {
  errors.push('api_key requis (BYOT - aucun fallback)');
}

// --- REQUIRED: messages ---
const messages = body.messages || ctx.messages;
if (!messages || !Array.isArray(messages) || messages.length === 0) {
  errors.push('messages requis (array non vide)');
}

// --- REQUIRED: callback_url ---
const callbackUrl = body.callback_url || ctx.callback_url;
if (!callbackUrl || typeof callbackUrl !== 'string') {
  errors.push('callback_url requis pour recevoir les paquets');
}

// --- REQUIRED: correlation_id ---
const correlationId = body.correlation_id || ctx.correlation_id;
if (!correlationId || typeof correlationId !== 'string') {
  errors.push('correlation_id requis pour le tracking');
}

// --- Optional ---
const system = body.system || ctx.system || null;
const maxTokens = parseInt(body.max_tokens || ctx.max_tokens || 4096);
const temperature = parseFloat(body.temperature ?? ctx.temperature ?? 0.7);
const metadata = body.metadata || ctx.metadata || {};

// Stream config with defaults
const streamConfig = {
  flush_timeout_ms: body.stream_config?.flush_timeout_ms || 500,
  flush_token_count: body.stream_config?.flush_token_count || 20,
  flush_size_bytes: body.stream_config?.flush_size_bytes || 4096
};

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    correlation_id: correlationId
  };
}

return {
  valid: true,
  provider: provider,
  model: model.trim(),
  api_key: apiKey.trim(),
  system: system,
  messages: messages,
  max_tokens: maxTokens,
  temperature: temperature,
  callback_url: callbackUrl,
  correlation_id: correlationId,
  stream_config: streamConfig,
  metadata: metadata,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  status: 'error',
  correlation_id: input.correlation_id || null,
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  }
};

// ============================================
// PREPARE STREAM REQUEST
// Retourne immédiatement { status: 'streaming' }
// puis déclenche le streaming asynchrone
// ============================================

const data = $json;

// Préparer la configuration pour le streaming
const streamRequest = {
  provider: data.provider,
  model: data.model,
  api_key: data.api_key,
  system: data.system,
  messages: data.messages,
  max_tokens: data.max_tokens,
  temperature: data.temperature,
  callback_url: data.callback_url,
  correlation_id: data.correlation_id,
  stream_config: data.stream_config,
  metadata: data.metadata,
  startTime: data.startTime
};

// Pour le moment, on passe les données au prochain node
// Le streaming réel nécessite un custom node ou script externe
return {
  immediate_response: {
    success: true,
    status: 'streaming',
    correlation_id: data.correlation_id,
    message: 'Stream initiated. Packets will be sent to callback_url.'
  },
  stream_request: streamRequest
};

