// ============================================
// PROCESS STREAM RESPONSE & SEND TO CALLBACK
// Note: n8n HTTP Request ne supporte pas le streaming SSE natif
// La réponse est reçue en entier (non-streamé)
// Pour un vrai streaming, utiliser un custom node ou script externe
// ============================================

const input = $input.first().json;
const prevData = $('Prepare Stream').first().json;
const req = prevData.stream_request;
const startTime = req.startTime || Date.now();
const latencyMs = Date.now() - startTime;

// Déterminer le provider depuis le flux
let provider = req.provider;
let text = '';
let usage = { input_tokens: 0, output_tokens: 0 };
let finishReason = 'stop';

// Parser selon le provider
if (provider === 'anthropic') {
  text = input.content?.[0]?.text || '';
  usage = {
    input_tokens: input.usage?.input_tokens || 0,
    output_tokens: input.usage?.output_tokens || 0
  };
  finishReason = input.stop_reason || 'end_turn';
} else if (provider === 'google') {
  const parts = input.candidates?.[0]?.content?.parts || [];
  text = parts.map(p => p.text || '').join('');
  usage = {
    input_tokens: input.usageMetadata?.promptTokenCount || 0,
    output_tokens: input.usageMetadata?.candidatesTokenCount || 0
  };
  finishReason = input.candidates?.[0]?.finishReason || 'STOP';
} else {
  // OpenAI / Mistral format
  text = input.choices?.[0]?.message?.content || '';
  usage = {
    input_tokens: input.usage?.prompt_tokens || 0,
    output_tokens: input.usage?.completion_tokens || 0
  };
  finishReason = input.choices?.[0]?.finish_reason || 'stop';
}

// Construire le paquet final
const finalPacket = {
  correlation_id: req.correlation_id,
  sequence: 1,
  events: [
    { type: 'content_block_delta', delta: { text: text } },
    { type: 'message_stop' }
  ],
  final: true,
  cumulative_tokens: usage.input_tokens + usage.output_tokens,
  usage: usage,
  provider: provider,
  model: req.model,
  duration_ms: latencyMs,
  timestamp: new Date().toISOString(),
  metadata: req.metadata
};

return {
  callback_url: req.callback_url,
  packet: finalPacket
};

