={{ (() => {
  const req = $json.stream_request;
  const b = { contents: req.messages, generationConfig: { maxOutputTokens: req.max_tokens, temperature: req.temperature } };
  if (req.system) b.systemInstruction = { parts: [{ text: req.system }] };
  return JSON.stringify(b);
})() }}

